-- Weekly Arena 2027-W02: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2027-W02', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2027-01-11T00:00:00.000Z', '2027-01-18T00:00:00.000Z', 60, 'published', $WK0653bf7b2b23$[{"id":"wk-2027-w02-01-61ac","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $27$ and $7$ and each non-parallel side has length $26$. Find its area.","type":"text","correctAnswer":"408","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $10$ and hypotenuse $26$.","solution":"The height is $\\sqrt{26^2-10^2}=24$, so the area is $\\tfrac12(27+7)(24)=408$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w02-02-28b9","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 4$. Find $x^{5} + \\dfrac{1}{x^{5}}$.","type":"text","correctAnswer":"724","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=4T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=4$ the recurrence gives $T_{5}=724$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w02-03-0ca5","title":"Coprime Count","topic":"Number Theory","level":"Intermediate","question":"How many integers $n$ with $1\\le n\\le 981$ are relatively prime to $14$?","type":"text","correctAnswer":"421","hint":"Remove multiples of 2, 7 using inclusion-exclusion.","solution":"Inclusion-exclusion over the primes 2, 7 leaves $421$ integers.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w02-04-cdbe","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $22$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=11$. Find $PA + PB + PT$.","type":"text","correctAnswer":"77","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=22^2/11=44$, so the sum is $11+44+22=77$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2027-w02-05-3bd8","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 1 \\pmod{5}$, $n\\equiv 5 \\pmod{7}$, $n\\equiv 6 \\pmod{9}$.","type":"text","correctAnswer":"96","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $96$ modulo $315$, and $96$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w02-06-1240","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 5-tuples $(x_1,\\dots,x_5)$ of non-negative integers satisfy $x_1+\\cdots+x_5=13$ with every $x_i\\le 6$?","type":"text","correctAnswer":"1330","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $1330$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2027-w02-07-5191","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{34} \\left\\lfloor \\frac{9k}{13} \\right\\rfloor$.","type":"text","correctAnswer":"396","hint":"Write $9k=13q+r$ and track how the remainder cycles with period $13$.","solution":"Evaluating each floor term and adding gives $396$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w02-08-765a","title":"Rearranging a Word","topic":"Combinatorics","level":"Advanced","question":"In how many distinct ways can the letters of $\\text{HLLLNNTT}$ be rearranged so that no two identical letters are adjacent?","type":"text","correctAnswer":"384","hint":"Count all arrangements, then use inclusion-exclusion by gluing identical letters together.","solution":"Inclusion-exclusion (confirmed by exhaustive enumeration) gives $384$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":4,"points":73,"difficulty":0.52},{"id":"wk-2027-w02-09-45b9","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 9t + 1 = 0$. Find the remainder when $r^{6} + s^{6}$ is divided by $1000$.","type":"text","correctAnswer":"802","hint":"Let $S_k=r^k+s^k$. Then $S_k=9S_{k-1}-1S_{k-2}$, with $S_0=2$, $S_1=9$.","solution":"Using $S_k=9S_{k-1}-1S_{k-2}$ from $S_0=2$, $S_1=9$ gives $S_{6}=492802$, whose remainder modulo $1000$ is $802$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w02-10-5b21","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(12,6)$ and $(2,9)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"45","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $96$ and the boundary has $B=8$ lattice points, so $I=(96-8+2)/2=45$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK0653bf7b2b23$::jsonb
